const publicStyle = '''
:root{color-scheme:dark;--bg:#101110;--surface:#20221e;--line:#30332b;--text:#e9ece2;--muted:#969d8c;--accent:#c1f45c}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,'Segoe UI',Arial,sans-serif;line-height:1.6;-webkit-font-smoothing:antialiased}a{color:inherit;text-decoration:none}a:hover{color:var(--accent)}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--accent);outline-offset:5px}header{border-bottom:1px solid #2a2d25;background:#121411;position:relative;z-index:2}header nav{max-width:1800px;margin:auto;min-height:72px;display:flex;align-items:center;gap:32px;padding:14px 32px}.brand{display:flex;align-items:center;gap:9px;letter-spacing:-1.4px;font-weight:800;font-size:28px;color:var(--accent)}.mark{color:var(--accent);font-size:36px;font-weight:400;line-height:1}.nav-links{display:flex;align-items:center;gap:34px;width:100%;margin-left:30px}.nav-links a{font-size:13px;color:#d6dbcf;font-weight:600}.nav-links a:hover{color:var(--accent)}.nav-links .nav-login{margin-left:auto;color:var(--muted);font-weight:400}.button{display:inline-flex;justify-content:center;align-items:center;gap:8px;border:1px solid transparent;border-radius:9px;background:var(--accent);color:#19200f;padding:10px 20px;font:inherit;font-size:12px;font-weight:700;cursor:pointer;white-space:nowrap;transition:background .2s,transform .2s}.button:hover{background:#d3ff7e;color:#19200f;transform:translateY(-1px)}.button.secondary{background:#242820;border-color:#414c33;color:var(--text)}.nav-links .button{color:#19200f;padding:9px 17px}
main{max-width:1800px;margin:auto;padding:38px 32px 70px}main:has(.hero){padding-top:0}.eyebrow{font-size:9px;letter-spacing:2.5px;text-transform:uppercase;color:#a4b88c;font-weight:600}.hero{position:relative;text-align:center;padding:42px 20px 30px;margin:0 -32px;border-bottom:1px solid #252b20;background:radial-gradient(ellipse at 48% 10%,#26391c88,transparent 57%),radial-gradient(ellipse at 85% 0%,#18352f66,transparent 45%)}.hero h1{font-size:clamp(27px,3vw,40px);line-height:1.2;letter-spacing:-1.3px;margin:12px 0 10px;font-weight:600}.hero h1 em{font-style:normal;color:#d1efaf}.hero>p{color:var(--muted);font-size:12px;margin:0 0 18px}.creation-tabs{display:inline-flex;gap:3px;padding:4px;background:#222a1e;border:1px solid #30392a;border-radius:10px;margin:0 auto 19px}.creation-tab{min-width:116px;padding:5px 20px;font-size:11px;color:var(--muted);border-radius:7px}.creation-tab.active{background:#39452d;color:#e4eddb;font-weight:600}.hero-upload{max-width:660px;min-height:125px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;margin:auto;position:relative;border:1px solid #69834c;border-radius:19px;background:linear-gradient(120deg,#1c2716bb,#111e18cc);box-shadow:0 0 45px #516e2110;transition:border-color .2s,background .2s}.hero-upload:hover{border-color:var(--accent);background:#222e1c}.hero-upload svg{width:27px;height:27px;color:#cbdfb3;margin-bottom:3px}.hero-upload strong{font-size:13px;font-weight:500;color:#e0e7d7}.hero-upload>span{font-size:10px;color:var(--muted)}.hero-upload .upload-arrow{position:absolute;right:19px;bottom:14px;color:var(--accent);font-size:20px}.hero-bottom{max-width:660px;margin:14px auto 0;display:flex;justify-content:space-between;align-items:center;gap:12px}.hero-flow-links{display:flex;align-items:center;gap:13px;color:var(--muted);font-size:10px}.hero-flow-links>span{color:#4d5c3d}.hero .hero-note{font-size:9px;color:#76836a;margin:12px 0 0}
.community{padding-top:22px}.community-toolbar{display:flex;align-items:center;gap:22px;flex-wrap:wrap}.community-title{display:flex;align-items:baseline;gap:15px;white-space:nowrap}.community-title h2{font-size:21px;font-weight:600;letter-spacing:-.6px;color:var(--accent);margin:0}.community-title>span{font-size:10px;color:#737e69;display:none}.community .categories{margin:0;gap:4px;flex:1}.community .category{border:0;padding:7px 11px;border-radius:6px;font-size:10px;white-space:nowrap}.community .category.active{background:#2c3521;color:var(--accent)}.community-search{font-size:10px;color:var(--muted);white-space:nowrap}.community-caption{display:flex;justify-content:space-between;gap:15px;color:#7f8a73;font-size:10px;margin:19px 0 15px}.community-caption>a{color:#a6b590}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px}.card{border:1px solid #30352a;background:var(--surface);border-radius:13px;overflow:hidden;transition:border-color .2s,transform .2s}.card:hover{border-color:#7f9a50;transform:translateY(-4px)}.preview{height:285px;background:radial-gradient(ellipse at 50% 45%,#3b4333,#22251f 75%);display:flex;align-items:center;justify-content:center;overflow:hidden}.preview img{width:100%;height:100%;object-fit:contain}.card-body{padding:14px 15px 16px;border-top:1px solid #343a2d}.card h3{font-size:13px;font-weight:500;margin:8px 0 4px;letter-spacing:-.15px}.card p{font-size:10px;color:var(--muted);margin:0}.tag-row{display:flex;justify-content:space-between;align-items:center;gap:8px}.tag{font-size:8px;letter-spacing:.5px;text-transform:uppercase;color:#b4c89a;background:#a4c8760c;border:1px solid #50613b66;border-radius:4px;padding:2px 5px}.format{font-size:8px;color:#869677}.categories{display:flex;gap:9px;flex-wrap:wrap;margin:24px 0}.category{font-size:11px;border:1px solid var(--line);border-radius:7px;padding:7px 14px;color:var(--muted)}.category:hover,.category.active{border-color:#6b8546;color:var(--accent);background:#95b35610}
.section-title{display:flex;align-items:baseline;justify-content:space-between;gap:20px;margin:14px 0}.section-title h1,.section-title h2{margin:0;line-height:1.3;font-size:29px;letter-spacing:-.6px}.section-title small{color:var(--muted);font-size:11px}.actions{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin-top:25px}.filters{padding:17px;border:1px solid var(--line);border-radius:12px;display:flex;gap:14px;align-items:end;background:#1b1f18;margin:22px 0}.field{display:flex;flex-direction:column;gap:6px;flex:1}.field label{color:var(--muted);font-size:11px}input,select{border:1px solid #3d4633;background:#141810;color:var(--text);padding:11px 13px;border-radius:8px;font:inherit;font-size:12px;width:100%;min-width:0}input::placeholder{color:#747e68}.notice{padding:48px 28px;border:1px dashed #3c4b2e;border-radius:14px;background:linear-gradient(120deg,#20281a66,#171c14);text-align:center;margin:20px 0}.notice h2{font-size:20px;font-weight:500;margin:0 0 10px}.notice p{font-size:12px;color:var(--muted);max-width:550px;margin:0 auto 20px}.muted{color:var(--muted);font-size:13px}.breadcrumb{color:var(--muted);font-size:12px;margin-bottom:25px}.detail{display:grid;grid-template-columns:1.3fr 1fr;gap:40px;max-width:1240px;margin:auto}.detail .preview{height:540px;border:1px solid var(--line);border-radius:16px}.detail h1{font-size:36px;line-height:1.2;letter-spacing:-1px;margin:16px 0}.detail .description{white-space:pre-wrap;color:var(--muted);font-size:13px}.details-list{display:grid;grid-template-columns:1fr 1fr;border-top:1px solid var(--line);margin:27px 0}.details-list dt,.details-list dd{padding:13px 0;margin:0;border-bottom:1px solid var(--line);font-size:12px}.details-list dt{color:var(--muted)}.details-list dd{text-align:right}.detail small{display:block;color:var(--muted);margin-top:18px;font-size:10px}.pagination{display:flex;align-items:center;justify-content:space-between;margin-top:30px;gap:15px}.prose{max-width:800px;margin:auto}.prose h1{font-size:36px;letter-spacing:-1px}.prose h2{font-size:20px;margin-top:32px}.prose p,.prose li{color:var(--muted);font-size:14px}footer{border-top:1px solid var(--line);padding:24px 32px;color:#7e8b71;font-size:10px}.footer-inner{max-width:1736px;margin:auto;display:flex;justify-content:space-between;gap:20px}.footer-links{display:flex;gap:22px}.skip{position:absolute;top:-80px;left:20px;background:var(--accent);color:#18200f;padding:10px 20px;z-index:10}.skip:focus{top:10px}.line{height:1px;background:var(--line);margin:40px 0}::selection{background:#688139;color:white}
@media(min-width:1500px){.grid{grid-template-columns:repeat(6,minmax(0,1fr))}.preview{height:300px}.community-title>span{display:block}.hero{padding-top:48px;padding-bottom:38px}.hero-upload{min-height:135px}}
@media(max-width:1200px){.community-toolbar{gap:15px}.community-search{display:none}.grid{grid-template-columns:repeat(4,minmax(0,1fr))}.preview{height:240px}.community .categories{order:3;flex-basis:100%}.community-toolbar>.button{margin-left:auto}.nav-links{gap:25px;margin-left:15px}}
@media(max-width:850px){.grid{grid-template-columns:repeat(3,minmax(0,1fr))}.preview{height:230px}.detail{grid-template-columns:1fr}.detail .preview{height:400px}.filters{flex-wrap:wrap}.field{min-width:170px}.nav-links{gap:20px}.nav-workspace{display:none}.hero{padding-top:35px}.hero h1{font-size:33px}}
@media(max-width:600px){header nav{padding:12px 18px;min-height:64px;gap:15px}.brand{font-size:24px}.mark{font-size:30px}.nav-links{margin-left:auto;width:auto;gap:10px}.nav-links a:not(.button){display:none}.nav-links .button{font-size:10px;padding:8px 12px}main{padding:26px 16px 45px}.hero{margin:0 -16px;padding:30px 20px 25px}.eyebrow{font-size:7px;letter-spacing:1.8px}.hero h1{font-size:29px;letter-spacing:-1px;max-width:300px;margin:14px auto 10px}.hero>p{font-size:11px;max-width:270px;margin:0 auto 20px}.hero-upload{min-height:130px;border-radius:15px}.hero-bottom{flex-direction:column-reverse;gap:14px}.hero-bottom>.button{width:100%;padding:11px}.hero-flow-links{gap:12px;font-size:9px}.hero .hero-note{font-size:8px;margin-top:12px}.community{padding-top:19px}.community-title h2{font-size:20px}.community .categories{flex-wrap:nowrap;overflow-x:auto;padding-bottom:5px}.community .category{font-size:9px;padding:6px 9px}.community-caption{font-size:8px;gap:8px;margin-top:14px}.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.preview{height:210px}.card{border-radius:10px}.card-body{padding:10px}.card h3{font-size:11px}.card p{font-size:9px}.format{font-size:7px}.tag{font-size:7px}.section-title{align-items:flex-start;flex-direction:column;gap:5px}.section-title h1,.section-title h2{font-size:25px}.filters{padding:12px}.filters .button{width:100%}.detail .preview{height:340px}.detail h1{font-size:29px}.footer-inner{flex-direction:column}.footer-links{flex-wrap:wrap}footer{padding:20px 16px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{transition:none!important}}
''';
